import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"泮水","description":"","frontmatter":{"title":"泮水","date":"2026-11-10T00:00:00.000Z","seq":34,"categories":["美文","诗经"],"collection":"《诗经 · 颂》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·颂/泮水.md","filePath":"blogs/诗经·颂/泮水.md"}'),p={name:"blogs/诗经·颂/泮水.md"};function c(l,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="泮水" tabindex="-1">泮水 <a class="header-anchor" href="#泮水" aria-label="Permalink to &quot;泮水&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　鲁颂·駉之什</p><div class="poem"><p class="poem-stanza">思乐泮水，薄采其芹。鲁侯戾止，言观其旂。其旂茷茷，鸾声哕哕。无小无大，从公于迈。</p><p class="poem-stanza">思乐泮水，薄采其藻。鲁侯戾止，其马蹻蹻。其马蹻蹻，其音昭昭。载色载笑，匪怒伊教。</p><p class="poem-stanza">思乐泮水，薄采其茆。鲁侯戾止，在泮饮酒。既饮旨酒，永锡难老。顺彼长道，屈此群丑。</p><p class="poem-stanza">穆穆鲁侯，敬明其德。敬慎威仪，维民之则。允文允武，昭假烈祖。靡有不孝，自求伊祜。</p><p class="poem-stanza">明明鲁侯，克明其德。既作泮宫，淮夷攸服。矫矫虎臣，在泮献馘。淑问如皋陶，在泮献囚。</p><p class="poem-stanza">济济多士，克广德心。桓桓于征，狄彼东南。烝烝皇皇，不吴不扬。不告于訩，在泮献功。</p><p class="poem-stanza">角弓其觩。束矢其搜。戎车孔博。徒御无斁。既克淮夷，孔淑不逆。式固尔犹，淮夷卒获。</p><p class="poem-stanza">翩彼飞鸮，集于泮林。食我桑黮，怀我好音。憬彼淮夷，来献其琛。元龟象齿，大赂南金。</p></div>',3)])])}const u=s(p,[["render",c]]);export{d as __pageData,u as default};
